export const RESPECTING_DIFFERENCES_ACTIVITIES = [
// FASE A — FONDASI / KONKRET (1-20): perbedaan pendapat itu wajar, mendengar, kritik ide bukan orang
{n:1,type:"mcq",micro:"Perbedaan pendapat itu wajar",q:"Ketika anggota tim punya pendapat berbeda tentang cara mengerjakan proyek, itu...",options:["Hal wajar & normal — orang punya pengalaman & cara berpikir berbeda","Tanda tim yang buruk","Berarti ada yang bodoh"],answer:0,explain:"Tim tanpa perbedaan pendapat sering hanya mengikuti satu suara. Perbedaan bisa menghasilkan keputusan lebih baik.",hint:"Wajar & normal, atau tanda buruk?"},
{n:2,type:"mcq",micro:"Kritik ide, bukan orang",q:"Cara menyampaikan ketidaksetujuan yang menjaga hubungan:",options:["Diam & memusuhi diam-diam","'Aku kurang setuju dengan ide itu karena...' — fokus pada idenya","'Kamu memang selalu punya ide aneh' — menyerang orangnya"],answer:1,explain:"Kamu bisa menolak ide dengan tegas tanpa menyerang atau merendahkan orang yang mengusulkannya.",hint:"Kritik idenya, atau serang orangnya?"},
{n:3,type:"mcq",micro:"Mendengar sebelum membantah",q:"Sebelum menyampaikan ketidaksetujuanmu, sebaiknya...",options:["Potong di tengah untuk menyampaikan pendapatmu","Menganggap kamu sudah tahu apa yang akan ia katakan","Dengarkan pendapat orang sampai selesai & pastikan kamu paham maksudnya"],answer:2,explain:"Membantah pendapat yang belum kamu pahami sepenuhnya sering meleset & terasa tidak menghormati.",hint:"Dengar & pahami dulu, atau potong?"},
{n:4,type:"mcq",micro:"Perbedaan bisa memperkuat",q:"Dua anggota punya ide berbeda untuk poster: satu ingin fokus gambar, satu fokus data. Hasil terbaik mungkin...",options:["Menggabungkan yang terbaik dari keduanya: gambar kuat + data ringkas yang jelas","Memilih satu & membuang yang lain sepenuhnya","Bertengkar sampai satu menyerah"],answer:0,explain:"Perbedaan pendapat sering bukan 'A atau B' tapi kesempatan menemukan 'A + B' yang lebih baik.",hint:"Gabungkan yang terbaik, atau buang satu / bertengkar?"},
{n:5,type:"mcq",micro:"Menghormati saat kalah suara",q:"Idemu kalah suara dalam keputusan tim. Sikap yang menghormati tim:",options:["Terus mengungkit bahwa idemu lebih baik","Sampaikan kekecewaan bila perlu, lalu dukung keputusan tim & beri yang terbaik","Menyabotase diam-diam karena kesal"],answer:1,explain:"Menerima kekalahan suara dengan lapang & tetap berkontribusi penuh adalah tanda kematangan.",hint:"Dukung keputusan tim, atau sabotase / ungkit?"},
{n:6,type:"mcq",micro:"Bertanya alasan",q:"Temanmu punya pendapat yang menurutmu aneh. Respons yang menghormati:",options:["'Ide kamu nggak masuk akal.'","Memutar mata & mengabaikan","'Aku penasaran, apa yang bikin kamu berpikir begitu?'"],answer:2,explain:"Bertanya alasan menunjukkan kamu menganggap pendapatnya layak dipertimbangkan, & sering mengungkap hal yang kamu lewatkan.",hint:"Tanya alasannya, atau meremehkan?"},
{n:7,type:"mcq",micro:"Perbedaan gaya kerja",q:"Anggota timmu suka mengerjakan tugas jauh sebelum tenggat; kamu suka mendekati tenggat. Sikap:",options:["Hormati perbedaan, tapi sepakati tenggat internal bersama yang bisa dipenuhi semua","Paksa semua bekerja dengan gayamu","Kritik gaya kerjanya sebagai salah"],answer:0,explain:"Perbedaan gaya bukan soal benar-salah. Yang penting: kesepakatan bersama soal kapan bagian harus jadi.",hint:"Hormati + sepakati tenggat bersama, atau paksa satu gaya?"},
{n:8,type:"mcq",micro:"Menyampaikan pendapat tanpa memaksa",q:"Cara menyampaikan pendapatmu di tim yang tetap terbuka:",options:["'Terserah kalian aja.' (padahal punya pendapat kuat)","'Menurutku sebaiknya begini, karena... Tapi aku terbuka kalau ada yang lihat berbeda.'","'Pokoknya harus begini. Titik.'"],answer:1,explain:"Menyampaikan pendapat dengan alasan + membuka ruang diskusi lebih efektif daripada memaksa atau menahan.",hint:"Pendapat + alasan + terbuka, atau memaksa / menahan?"},
{n:9,type:"order",micro:"Menanggapi pendapat yang berbeda",q:"Urutkan cara menanggapi anggota yang pendapatnya berbeda darimu.",items:["Dengarkan sampai selesai tanpa memotong","Ulangi inti pendapatnya untuk memastikan kamu paham","Tanyakan alasannya bila belum jelas","Sampaikan pandanganmu dengan alasan, fokus pada idenya"],answer:[0,1,2,3],explain:"Dengar → pahami → tanya alasan → sampaikan pandanganmu (soal ide). Bukan langsung membantah.",hint:"Apa yang dilakukan sebelum menyampaikan pandanganmu?"},
{n:10,type:"mcq",micro:"Nada saat tidak setuju",q:"Nada suara yang menjaga diskusi tetap sehat saat ada perbedaan pendapat:",options:["Meninggi & mengejek","Sinis & menyindir","Tenang & ramah, meski isinya tegas menolak"],answer:2,explain:"Isi bisa tegas ('aku tidak setuju'), tapi nada yang tenang menjaga orang tidak merasa diserang.",hint:"Tenang & ramah, atau meninggi / sinis?"},
{n:11,type:"tf",micro:"Perbedaan pendapat bisa berguna",q:"Benar atau Salah: Perbedaan pendapat dalam tim, bila dibahas dengan hormat, sering menghasilkan keputusan yang lebih baik daripada bila semua langsung setuju tanpa berpikir.",answer:true,explain:"Perbedaan pendapat memaksa tim menimbang beberapa sisi & menangkap risiko atau ide yang mungkin terlewat.",hint:"Bisa menghasilkan keputusan lebih baik, atau selalu merugikan?"},
{n:12,type:"tf",micro:"Menghormati = harus setuju?",q:"Benar atau Salah: Menghormati pendapat orang lain berarti kamu wajib pada akhirnya menyetujui pendapat mereka.",answer:false,explain:"Sebaliknya, kamu bisa mendengarkan dengan hormat, mempertimbangkan sungguh-sungguh, lalu tetap tidak setuju — selama kamu menyampaikannya dengan cara yang menghargai orangnya.",hint:"Hormat = wajib setuju, atau bisa dengar lalu tetap berbeda?"},
{n:13,type:"mcq",micro:"Perbedaan latar belakang",q:"Anggota timmu dari daerah/keluarga berbeda punya kebiasaan & cara pandang berbeda. Sikap:",options:["Anggap perbedaan itu bisa memperkaya tim; bertanya bila tidak paham, bukan langsung menilai 'aneh' atau 'salah'","Menganggap caranya pasti kurang tepat","Menghindari bekerja dengannya"],answer:0,explain:"Keberagaman sudut pandang menangkap titik buta yang tim seragam lewatkan — asalkan dikelola dengan hormat.",hint:"Memperkaya, atau 'aneh/salah'?"},
{n:14,type:"mcq",micro:"Menahan diri dari langsung menolak",q:"Saat mendengar ide yang tidak kamu suka, kebiasaan baik:",options:["Diam & menolak dalam hati tanpa bilang","Tahan reaksi awal, cari dulu apa yang mungkin bagus atau masuk akal dari ide itu, baru sampaikan kekhawatiranmu","Langsung berkata 'nggak' sebelum orang selesai bicara"],answer:1,explain:"Reaksi 'nggak' yang cepat sering emosi. Mencari sisi baik dulu membuat tanggapanmu lebih adil & diskusi lebih produktif.",hint:"Tahan + cari sisi baik dulu, atau langsung 'nggak' / diam menolak?"},
{n:15,type:"mcq",micro:"Perbedaan bukan pertengkaran",q:"Beda 'diskusi yang sehat tentang perbedaan pendapat' & 'pertengkaran':",options:["Keduanya sama","Diskusi sehat berarti tidak ada perbedaan","Diskusi sehat: fokus pada ide, semua didengar, tujuannya keputusan lebih baik. Pertengkaran: fokus menyerang & menang, orang merasa terluka"],answer:2,explain:"Perbedaan pendapat tidak harus menjadi pertengkaran. Yang membedakannya adalah fokus (ide vs orang) & tujuan (lebih baik vs menang).",hint:"Fokus ide + keputusan lebih baik, atau menyerang + menang?"},
{n:16,type:"mcq",micro:"Menghargai anggota pendiam yang berbeda",q:"Anggota pendiam menyampaikan pendapat yang berbeda dari mayoritas dengan suara pelan. Sikap tim:",options:["Beri perhatian penuh, minta ia menjelaskan lebih lanjut, & timbang pendapatnya serius — jangan langsung tenggelamkan dengan suara mayoritas","Abaikan karena dia sendirian & pelan","Suruh dia ikut mayoritas saja"],answer:0,explain:"Pendapat minoritas kadang menangkap risiko yang mayoritas lewatkan. Dengarkan sebelum memutuskan.",hint:"Beri perhatian & timbang serius, atau tenggelamkan / suruh ikut?"},
{n:17,type:"mcq",micro:"Mengakui poin lawan",q:"Saat berdiskusi & lawan bicara menyampaikan poin yang benar, sikap yang menghormati:",options:["Langsung ganti topik","Akui: 'Poin kamu soal biaya itu betul, aku belum kepikiran' — lalu lanjutkan diskusi","Pura-pura tidak mendengar poin bagusnya"],answer:1,explain:"Mengakui poin yang benar dari lawan menunjukkan kamu berdiskusi untuk mencari yang terbaik, bukan sekadar menang.",hint:"Akui poin bagusnya, atau abaikan / alihkan?"},
{n:18,type:"mcq",micro:"Perbedaan pendapat soal selera",q:"Tim berdebat soal warna poster (selera). Cara menyelesaikan yang tidak berlarut:",options:["Berdebat berjam-jam mencari 'warna yang benar'","Yang paling ngotot yang menang","Sadari ini soal selera (tidak ada yang 'benar'), lalu voting cepat atau serahkan ke penanggung jawab desain dengan masukan"],answer:2,explain:"Tidak semua perbedaan pendapat perlu diperdebatkan panjang. Soal selera bisa diputuskan cepat.",hint:"Sadari soal selera + voting/serahkan, atau debat panjang / ngotot?"},
{n:19,type:"mcq",micro:"Menjaga hubungan setelah berbeda",q:"Setelah diskusi yang cukup panas soal perbedaan pendapat, sikap yang menjaga tim:",options:["Tegaskan bahwa perbedaan itu soal ide, bukan pribadi: 'Kita beda pendapat soal ini, tapi kita tetap satu tim ya.'","Memusuhi orang yang berbeda pendapat setelahnya","Menyimpan dendam"],answer:0,explain:"Menegaskan bahwa perbedaan ide tidak mengubah hubungan menjaga tim tetap solid setelah diskusi.",hint:"Tegaskan tetap satu tim, atau memusuhi / dendam?"},
{n:20,type:"open",micro:"Menanggapi perbedaan pendapat",q:"Dalam rapat kelompok, temanmu Rian mengusulkan topik proyek yang menurutmu terlalu sulit & berisiko tidak selesai tepat waktu. Rian terlihat bersemangat. Tulis bagaimana kamu akan menyampaikan ketidaksetujuanmu dengan menghormati Rian, lalu jelaskan pilihanmu.",sample:"Yang akan kukatakan: 'Rian, aku suka semangatmu soal topik ini, dan idenya memang menarik. Tapi aku agak khawatir soal waktu — topik ini butuh riset yang dalam dan mungkin data yang sulit kita dapat dalam 3 minggu. Menurutmu, gimana kalau kita ambil bagian yang lebih kecil dari topik itu, atau kita cari topik yang mirip tapi lebih terjangkau? Aku pengin dengar juga pendapat yang lain.' Penjelasan pilihanku: (1) Aku mulai dengan mengakui sisi baik idenya dan semangat Rian, supaya ia tidak merasa langsung ditolak mentah-mentah. (2) Aku menyampaikan kekhawatiranku dengan alasan yang spesifik (waktu, kesulitan data), fokus pada risiko idenya, bukan menyebut Rian 'nggak realistis' atau menyerang dia. (3) Aku menawarkan alternatif (memperkecil cakupan atau topik mirip yang lebih terjangkau) supaya diskusi bergerak ke solusi, bukan sekadar menolak. (4) Aku membuka ruang untuk pendapat anggota lain, supaya keputusan diambil bersama dan bukan hanya adu aku vs Rian.",explain:"Jawaban baik: mengakui sisi baik ide + semangat Rian dulu, menyampaikan ketidaksetujuan dengan alasan spesifik yang fokus pada risiko ide (bukan menyerang Rian), menawarkan alternatif konkret, dan membuka ruang untuk pendapat anggota lain — lalu menjelaskan alasan tiap pilihan.",hint:"Akui sisi baik + semangatnya, sampaikan kekhawatiran dengan alasan spesifik (soal ide), tawarkan alternatif, buka ruang pendapat lain."},

// FASE B — PEMAHAMAN (21-40)
{n:21,type:"classify",micro:"Menanggapi perbedaan: hormat vs merendahkan",q:"Kelompokkan tiap respons ke 'Menghormati perbedaan' atau 'Merendahkan'.",items:["'Aku lihatnya beda, ini alasanku...'","'Kok bisa mikir gitu sih, aneh banget.'","'Poinmu soal X aku setuju, tapi soal Y aku ragu karena...'","'Terserah, ngapain juga aku dengerin.'"],groups:["Menghormati perbedaan","Merendahkan"],answer:{"Menghormati perbedaan":["'Aku lihatnya beda, ini alasanku...'","'Poinmu soal X aku setuju, tapi soal Y aku ragu karena...'"],"Merendahkan":["'Kok bisa mikir gitu sih, aneh banget.'","'Terserah, ngapain juga aku dengerin.'"]},explain:"Menghormati: menyampaikan pandangan beda dengan alasan, mengakui poin yang benar. Merendahkan: menyebut pendapat 'aneh', menolak mendengar.",hint:"Menyampaikan beda dengan alasan, atau meremehkan / menolak mendengar?"},
{n:22,type:"mcq",micro:"Steelman vs strawman",q:"'Steelman' sebuah pendapat berarti...",options:["Mengabaikan pendapat lawan","Menyampaikan ulang pendapat lawan dalam versi terkuat & teradilnya sebelum menanggapinya","Membuat versi terlemah pendapat lawan agar mudah dibantah"],answer:1,explain:"Menanggapi versi terkuat pendapat lawan ('steelman') lebih menghormati & lebih meyakinkan daripada menyerang versi lemah ('strawman').",hint:"Versi terkuat & teradil, atau versi terlemah?"},
{n:23,type:"mcq",micro:"Perbedaan fakta vs perbedaan nilai",q:"Beda 'perbedaan pendapat soal fakta' & 'perbedaan soal nilai/prioritas':",options:["Keduanya sama & diselesaikan dengan cara sama","Perbedaan nilai selalu berarti salah satu pihak jahat","Fakta bisa dicek (mis. 'acara mulai jam 8 atau 9'); nilai/prioritas soal apa yang lebih penting bagi tiap orang & butuh kompromi, bukan pembuktian"],answer:2,explain:"Perbedaan fakta diselesaikan dengan mengecek. Perbedaan nilai/prioritas diselesaikan dengan memahami & berkompromi.",hint:"Fakta dicek, nilai dikompromikan — atau sama saja?"},
{n:24,type:"mcq",micro:"Menghargai tanpa menyerah pada tekanan",q:"Menghormati pendapat mayoritas TIDAK berarti...",options:["Kamu harus mengubah pendapatmu hanya karena kamu sendirian; kamu tetap boleh menyuarakan pandangan berbeda dengan sopan","Kamu boleh menyabotase keputusan mayoritas","Kamu wajib diam selamanya"],answer:0,explain:"Menghormati mayoritas = menerima keputusan bersama setelah menyuarakan pandanganmu, bukan membungkam diri sendiri sebelum bicara.",hint:"Tetap boleh menyuarakan beda dengan sopan, atau harus ikut karena sendirian?"},
{n:25,type:"mcq",micro:"Perbedaan pendapat & ego",q:"Kadang orang mempertahankan pendapat bukan karena yakin benar, tapi karena...",options:["Perbedaan pendapat tidak ada hubungannya dengan ego","Gengsi / tidak mau terlihat kalah — menyadari ini pada diri sendiri membantu kamu lebih terbuka berubah pikiran","Mereka selalu benar"],answer:1,explain:"Membedakan 'aku yakin ini benar' dari 'aku tidak mau kalah' membuatmu lebih jujur & terbuka dalam diskusi.",hint:"Gengsi bisa jadi alasan, atau tak ada hubungan dengan ego?"},
{n:26,type:"mcq",micro:"Menghargai lewat bahasa tubuh",q:"Bahasa tubuh yang menunjukkan kamu menghormati pendapat berbeda saat diskusi:",options:["Menyilangkan tangan & memalingkan badan","Melihat HP sambil orang bicara","Menghadap pembicara, kontak mata, mengangguk saat mengikuti, tidak memutar mata atau menghela napas keras"],answer:2,explain:"Bahasa tubuh terbuka menyampaikan 'aku mendengarmu' bahkan saat kamu tidak setuju.",hint:"Menghadap + angguk, atau memalingkan / memutar mata?"},
{n:27,type:"tf",micro:"Tim seragam lebih baik?",q:"Benar atau Salah: Tim yang semua anggotanya selalu setuju & tidak pernah berbeda pendapat biasanya menghasilkan keputusan yang lebih baik daripada tim yang punya perbedaan pendapat.",answer:false,explain:"Sebaliknya, tim yang selalu setyju berisiko 'groupthink' — mengikuti satu suara tanpa memeriksa. Perbedaan pendapat yang dibahas baik menangkap kesalahan & memperkaya pilihan.",hint:"Selalu setuju = lebih baik, atau berisiko tidak diperiksa?"},
{n:28,type:"tf",micro:"Kritik ide bisa terasa seperti serangan pribadi",q:"Benar atau Salah: Bahkan kritik yang ditujukan pada ide (bukan orang) bisa terasa menyakitkan bagi si pengusul, jadi menyampaikannya dengan lembut & mengakui usahanya tetap penting.",answer:true,explain:"Orang sering merasa terikat pada idenya. Nada yang baik & pengakuan atas usaha membantu ia menerima kritik ide tanpa merasa diserang.",hint:"Kritik ide bisa tetap menyakitkan, atau tak berpengaruh?"},
{n:29,type:"mcq",micro:"Menghargai & mengubah pikiran",q:"Mengubah pendapatmu setelah mendengar argumen yang lebih baik adalah tanda...",options:["Kekuatan & keterbukaan berpikir, bukan kelemahan","Kekalahan yang memalukan","Kamu tidak punya pendirian"],answer:0,explain:"Orang yang tidak pernah berubah pikiran meski ada bukti lebih baik sebenarnya keras kepala, bukan berpendirian teguh.",hint:"Kekuatan & keterbukaan, atau kekalahan?"},
{n:30,type:"order",micro:"Diskusi perbedaan pendapat yang produktif",q:"Urutkan tahap diskusi tim yang punya dua pendapat berbeda.",items:["Tiap pihak menjelaskan pendapat & alasannya tanpa dipotong","Tiap pihak mengulang pendapat lawan sampai lawan berkata 'ya, itu maksudku'","Cari titik temu & poin yang disepakati kedua pihak","Timbang berdasarkan tujuan tim & putuskan bersama; semua dukung hasilnya"],answer:[0,1,2,3],explain:"Jelaskan → saling memantulkan → cari titik temu → putuskan bersama. Bukan adu keras sampai satu menyerah.",hint:"Apa yang dilakukan sebelum mencari titik temu?"},
{n:31,type:"mcq",micro:"Menghargai saat kamu yakin benar",q:"Kamu sangat yakin pendapatmu benar & anggota lain salah. Sikap yang tetap menghormati:",options:["Memaksakan pendapatmu tanpa mendengar","Sampaikan keyakinanmu dengan alasan & bukti, tetap dengarkan sanggahan mereka, & akui bila ada kemungkinan kamu keliru","Menyebut mereka bodoh karena tidak melihat 'yang jelas'"],answer:1,explain:"Yakin benar bukan izin untuk merendahkan. Bahkan saat kamu benar, cara menyampaikan menentukan apakah orang mau menerima.",hint:"Alasan + tetap mendengar + akui kemungkinan keliru, atau merendahkan / memaksa?"},
{n:32,type:"tf",micro:"Perbedaan pendapat & pertemanan",q:"Benar atau Salah: Kalau kamu sering berbeda pendapat dengan seseorang, itu tanda kalian tidak cocok berteman & sebaiknya menjaga jarak.",answer:false,explain:"Sebaliknya, pertemanan yang sehat memberi ruang untuk berbeda. Yang merusak bukan perbedaannya, tapi cara yang tidak menghormati.",hint:"Bisa berteman + sering berbeda, atau perbedaan pasti merusak?"},
{n:33,type:"mcq",micro:"Menghargai lewat memberi waktu",q:"Anggota timmu butuh waktu memikirkan sebelum menyampaikan pendapat, sementara kamu cepat merespons. Sikap:",options:["Anggap diamnya berarti setuju","Desak dia menjawab cepat","Beri jeda & ruang; tanyakan pendapatnya secara khusus setelah diskusi berjalan sebentar — jangan anggap diamnya berarti setuju"],answer:2,explain:"Orang yang berpikir lebih lambat sering punya pendapat berharga. Memberi ruang menghormati cara berpikirnya.",hint:"Beri jeda + tanyakan khusus, atau anggap setuju / desak?"},
{n:34,type:"mcq",micro:"Perbedaan pendapat soal pembagian tugas",q:"Kamu & anggota lain tidak sepakat siapa yang seharusnya mengerjakan bagian sulit. Cara menyelesaikan:",options:["Bahas terbuka: pertimbangkan kekuatan, beban keseluruhan, & ketersediaan; cari pembagian yang dirasa adil kedua pihak","Yang lebih keras yang menentukan","Diam & kesal dengan pembagian yang ada"],answer:0,explain:"Perbedaan soal pembagian diselesaikan dengan diskusi berbasis kriteria adil, bukan dominasi atau kekesalan terpendam.",hint:"Bahas berbasis kriteria adil, atau dominasi / pendam?"},
{n:35,type:"mcq",micro:"Menghargai sambil tetap jujur",q:"Menghormati pendapat berbeda TIDAK berarti kamu harus...",options:["Mendengarkan sungguh-sungguh","Berpura-pura setuju atau menyembunyikan kekhawatiran seriusmu","Menyampaikan pandanganmu dengan sopan"],answer:1,explain:"Menghormati = mendengar & menyampaikan dengan cara yang baik, bukan menyerahkan kejujuran. Kekhawatiran serius tetap perlu disuarakan.",hint:"Berpura-pura setuju, atau sopan + tetap jujur?"},
{n:36,type:"mcq",micro:"Konflik ide vs konflik pribadi",q:"Kalau perbedaan pendapat mulai bergeser jadi serangan pribadi ('kamu memang selalu begitu'), sikap yang menyehatkan:",options:["Balas menyerang pribadi","Tinggalkan diskusi tanpa kata","Kembalikan ke isi: 'Ayo kita fokus ke idenya, bukan ke orangnya. Menurutku soal ide X...'"],answer:2,explain:"Mengarahkan kembali diskusi ke ide saat mulai jadi personal menjaga diskusi tetap produktif & hubungan tetap utuh.",hint:"Kembalikan ke isi, atau balas menyerang / pergi?"},
{n:37,type:"tf",micro:"Menghargai perbedaan bisa dilatih",q:"Benar atau Salah: Kemampuan menghadapi perbedaan pendapat dengan tenang adalah sifat bawaan; orang yang mudah defensif tidak bisa berubah.",answer:false,explain:"Sebaliknya, menahan reaksi awal, bertanya alasan, & memantulkan pendapat lawan semuanya keterampilan yang membaik dengan latihan sadar.",hint:"Bisa dilatih, atau bawaan tetap?"},
{n:38,type:"mcq",micro:"Menghargai pendapat orang yang lebih muda/kurang berpengalaman",q:"Anggota tim yang lebih muda / baru menyampaikan pendapat berbeda. Sikap:",options:["Timbang berdasarkan isi & alasannya, bukan berdasarkan usia/pengalaman; orang baru kadang melihat hal yang orang lama lewatkan","Abaikan karena dia belum berpengalaman","Suruh dia diam & belajar dulu"],answer:0,explain:"Ide dinilai dari kualitasnya, bukan dari siapa yang mengucapkannya. 'Mata segar' sering menangkap hal yang orang terbiasa lewatkan.",hint:"Timbang isinya, atau tolak karena usia?"},
{n:39,type:"mcq",micro:"Perbedaan pendapat yang tidak perlu diselesaikan",q:"Beberapa perbedaan pendapat dalam tim...",options:["Selalu berarti tim gagal","Tidak perlu diselesaikan sampai satu pihak menang — bisa dibiarkan (mis. selera pribadi yang tidak memengaruhi hasil) atau disepakati 'kita lihat berbeda & itu tidak apa-apa'","Selalu harus diselesaikan dengan satu pemenang"],answer:1,explain:"Tidak semua perbedaan perlu resolusi. Yang memengaruhi hasil diputuskan; yang tidak bisa dibiarkan berdampingan.",hint:"Sebagian bisa dibiarkan berdampingan, atau semua harus ada pemenang?"},
{n:40,type:"open",micro:"Menganalisis diskusi yang buruk",q:"Dalam rapat, Sinta mengusulkan cara A, Bagas berkata 'Itu ide bodoh, jelas cara B lebih baik' tanpa alasan, Sinta membalas 'Kamu emang nggak pernah ngehargain orang', dan rapat berhenti dengan semua kesal. Jelaskan minimal 3 kesalahan dalam diskusi ini, lalu tulis ulang bagaimana Bagas & Sinta seharusnya menanggapi satu sama lain.",sample:"Kesalahan: (1) Bagas menyerang ide dengan label ('ide bodoh') tanpa memberi alasan — ini merendahkan, bukan kritik yang membangun, dan tidak membantu tim menilai. (2) Bagas menyatakan cara B 'jelas lebih baik' juga tanpa alasan — jadi tidak ada yang bisa didiskusikan, hanya klaim. (3) Sinta membalas dengan serangan pribadi ('kamu nggak pernah ngehargain orang') — perbedaan ide bergeser jadi konflik karakter. (4) Tidak ada yang mengembalikan diskusi ke isi, jadi rapat berhenti tanpa hasil. Versi yang lebih baik: Bagas: 'Sinta, aku lihatnya agak beda. Menurutku cara B mungkin lebih cepat karena kita nggak perlu beli bahan tambahan. Tapi coba jelasin lagi, apa kelebihan cara A yang kamu lihat?' Sinta: 'Cara A memang butuh bahan tambahan, tapi hasilnya lebih tahan lama. Kalau soal kecepatan, poin kamu betul. Gimana kalau kita pakai cara B untuk bagian yang nggak kelihatan, dan cara A untuk bagian utama?' — keduanya memberi alasan, mengakui poin lawan, dan bergerak ke solusi gabungan.",explain:"Jawaban baik menyebut minimal 3 kesalahan (menyerang ide dengan label tanpa alasan, klaim tanpa alasan, serangan pribadi balasan, tidak ada yang mengembalikan ke isi) dan menulis ulang tanggapan keduanya menjadi: memberi alasan spesifik, bertanya/mengakui poin lawan, dan bergerak ke solusi.",hint:"Cari: label tanpa alasan, klaim tanpa alasan, serangan pribadi, tak ada yang kembali ke isi. Tulis ulang dengan alasan + mengakui poin lawan + cari solusi."},

// FASE C — PENERAPAN (41-60)
{n:41,type:"mcq",micro:"Skenario: kamu satu-satunya yang berbeda",q:"Seluruh tim setuju rencana X, hanya kamu yang khawatir. Sikap:",options:["Diam karena kamu sendirian","Terus menolak & menghambat sampai tim menyerah","Sampaikan kekhawatiranmu sekali dengan jelas & alasan spesifik; kalau tim tetap memilih X setelah mendengar, dukung keputusan itu"],answer:2,explain:"Menyuarakan pandangan minoritas sekali dengan jelas memenuhi tanggung jawabmu; setelah itu, mendukung keputusan tim.",hint:"Suarakan sekali lalu dukung, atau diam / menghambat?"},
{n:42,type:"mcq",micro:"Skenario: anggota memaksakan pendapatnya",q:"Seorang anggota selalu memaksakan pendapatnya & tidak mau mendengar yang lain. Sikap tim:",options:["Ingatkan dengan tenang bahwa keputusan diambil bersama & semua pendapat perlu didengar; minta ia menjelaskan alasannya lalu beri giliran yang lain","Menyerah & selalu ikut dia","Semua ikut memaksakan pendapat masing-masing balik"],answer:0,explain:"Menegakkan 'semua didengar' dengan tenang lebih efektif daripada menyerah atau membalas dengan memaksa juga.",hint:"Tegakkan 'semua didengar', atau menyerah / balas memaksa?"},
{n:43,type:"mcq",micro:"Skenario: perbedaan pendapat & tenggat mepet",q:"Tim berdebat soal pendekatan & tenggat sudah dekat. Sikap yang produktif:",options:["Koordinator memutuskan diam-diam tanpa mendengar","Batasi waktu diskusi: 'Kita bahas 10 menit lagi, dengar dua sisi, lalu voting/putuskan. Kita nggak punya waktu debat panjang.'","Terus berdebat sampai satu menyerah meski tenggat lewat"],answer:1,explain:"Saat waktu terbatas, batasi diskusi lalu putuskan dengan mekanisme yang disepakati — bukan debat tanpa akhir atau keputusan sepihak.",hint:"Batasi waktu + putuskan dengan mekanisme, atau debat tanpa akhir / sepihak?"},
{n:44,type:"mcq",micro:"Skenario: menghargai pendapat soal hal yang kamu kuasai",q:"Kamu ahli di bidang tertentu & anggota lain (bukan ahli) punya pendapat berbeda. Sikap:",options:["Tolak langsung karena kamu ahli","Merasa tersinggung ada yang berbeda pendapat di bidangmu","Dengarkan pendapatnya — mungkin ia melihat dari sudut yang kamu lewatkan; jelaskan pertimbangan teknismu dengan sabar, bukan meremehkan"],answer:2,explain:"Keahlian bukan izin meremehkan. Orang non-ahli kadang mengajukan pertanyaan atau sudut pandang yang berharga.",hint:"Dengar + jelaskan sabar, atau tolak / tersinggung?"},
{n:45,type:"order",micro:"Menengahi dua anggota yang berbeda pendapat",q:"Urutkan cara menengahi dua teman tim yang berdebat sengit soal ide.",items:["Minta keduanya berhenti sejenak & bicara bergantian","Minta tiap orang menjelaskan idenya + alasannya, yang lain menyimak tanpa memotong","Minta tiap orang mengulang inti ide lawannya dengan adil","Bantu mereka menemukan titik temu atau opsi gabungan, lalu putuskan bersama tim"],answer:[0,1,2,3],explain:"Hentikan adu mulut → jelaskan bergantian → saling memantulkan → cari titik temu. Menengahi = memfasilitasi pemahaman.",hint:"Apa yang dilakukan sebelum mencari titik temu?"},
{n:46,type:"mcq",micro:"Skenario: pendapatmu diabaikan berulang",q:"Kamu beberapa kali menyampaikan pendapat berbeda tapi selalu diabaikan tanpa dibahas. Sikap:",options:["Sampaikan pola ini dengan tenang: 'Aku beberapa kali usul soal ini tapi belum sempat dibahas. Boleh kita pertimbangkan sebentar?'","Berhenti menyampaikan pendapat selamanya","Menyampaikan dengan marah & menuduh"],answer:0,explain:"Menyebut pola (diabaikan) + meminta ruang pembahasan, tenang & spesifik — bukan menyerah atau menuduh.",hint:"Sebut pola + minta ruang bahas, atau menyerah / menuduh?"},
{n:47,type:"mcq",micro:"Skenario: perbedaan pendapat soal nilai",q:"Timmu berbeda soal apakah proyek harus 'seaman mungkin' atau 'seambisius mungkin'. Ini perbedaan nilai/prioritas. Cara menyelesaikan:",options:["Yang paling banyak bicara menentukan","Pahami apa yang penting bagi tiap pihak, lalu cari keseimbangan yang bisa diterima (mis. ambisius di bagian inti, aman di bagian lain)","Buktikan siapa yang 'benar' soal aman vs ambisius"],answer:1,explain:"Perbedaan nilai tidak diselesaikan dengan pembuktian — melainkan dengan memahami prioritas tiap pihak & mencari keseimbangan.",hint:"Pahami prioritas + cari keseimbangan, atau buktikan siapa benar?"},
{n:48,type:"mcq",micro:"Skenario: anggota berubah pikiran",q:"Seorang anggota yang tadinya bersikeras dengan idenya, setelah mendengar diskusi, berkata 'oke, kalian benar, aku ganti pendapat'. Sikap tim:",options:["Ejek: 'Tuh kan, dari tadi juga.'","Anggap dia plin-plan","Hargai keterbukaannya — jangan mengejek 'nah kan' atau membuatnya menyesal sudah berubah pikiran"],answer:2,explain:"Kalau tim mengejek orang yang berubah pikiran, orang lain jadi takut mengakui saat mereka keliru — diskusi jadi macet oleh gengsi.",hint:"Hargai keterbukaannya, atau ejek / anggap plin-plan?"},
{n:49,type:"mcq",micro:"Skenario: perbedaan pendapat dengan guru/pembimbing",q:"Kamu tidak setuju dengan arahan guru soal proyek. Cara menyampaikan dengan hormat:",options:["'Bu, boleh saya sampaikan pandangan berbeda? Menurut saya pendekatan lain mungkin lebih cocok karena... Tapi kami ikut keputusan Ibu.'","Mengabaikan arahan guru diam-diam","Membantah keras di depan kelas"],answer:0,explain:"Menyampaikan pandangan berbeda ke figur otoritas: minta izin, beri alasan, hormat, & menerima keputusan akhir.",hint:"Minta izin + alasan + hormat, atau abaikan / membantah keras?"},
{n:50,type:"open",micro:"Menyelesaikan perbedaan pendapat tim",q:"Timmu terbagi dua soal cara presentasi: Kelompok 1 (Ana, Budi) ingin presentasi formal dengan slide padat data; Kelompok 2 (Cici, Deni) ingin presentasi bercerita dengan sedikit slide. Keduanya punya alasan. Sebagai anggota kelima, rancang bagaimana kamu membantu tim menyelesaikan ini dengan menghormati kedua sisi (minimal 5 langkah).",sample:"(1) Kumpulkan tim & minta tiap kelompok menjelaskan pendekatan mereka + alasannya secara bergantian, tanpa dipotong. Ana-Budi: data padat meyakinkan penilai bahwa riset kami serius. Cici-Deni: cerita membuat penonton ingat pesan utama & tidak bosan. (2) Minta tiap kelompok mengulang inti pendekatan kelompok lain dengan adil, sampai kelompok itu berkata 'ya, itu maksud kami' — supaya semua benar-benar memahami sisi lawan, bukan versi karikaturnya. (3) Cari titik temu: sebenarnya keduanya sama-sama ingin presentasi yang meyakinkan & diingat. Perbedaannya soal cara. (4) Tawarkan opsi gabungan: buka dengan cerita singkat yang menarik (usul Kelompok 2), lalu sampaikan 2-3 poin data terpenting di slide yang bersih & jelas (bukan padat — kompromi), tutup dengan kembali ke cerita. Ini memakai kekuatan kedua pendekatan. (5) Kalau masih ada ketidaksepakatan soal detail, timbang berdasarkan tujuan (nilai + kesan penonton) & kriteria penilaian guru, lalu putyskan bersama (voting atau serahkan keputusan final ke penanggung jawab presentasi dengan masukan semua). (6) Setelah diputuskan, semua mendukung & memberi yang terbaik; tegaskan bahwa perbedaan tadi soal ide, bukan pribadi.",explain:"Jawaban baik: minta tiap sisi menjelaskan + alasan bergantian, minta saling memantulkan sampai diakui, cari titik temu (tujuan sama), tawarkan opsi gabungan yang memakai kekuatan kedua pendekatan, timbang berdasarkan tujuan/kriteria & putuskan bersama, lalu semua mendukung & tegaskan ini soal ide bukan pribadi.",hint:"Jelaskan bergantian → saling memantulkan → titik temu (tujuan sama) → opsi gabungan → timbang berdasarkan tujuan & putuskan bersama → semua dukung."},
{n:51,type:"mcq",micro:"Skenario: menghargai lewat memberi kredit ide",q:"Ide gabungan tim sebenarnya berawal dari usul anggota yang tadinya kalah suara. Sikap yang menghormati:",options:["Tidak menyebut siapa pun","Akui: 'Ide ini sebenarnya berkembang dari usul [nama] tadi.' — mengakui kontribusi meski usul awalnya tidak langsung dipakai","Klaim ide gabungan sebagai milik mayoritas"],answer:1,explain:"Menghargai berarti mengakui kontribusi orang bahkan saat usul awalnya harus dimodifikasi. Itu membuat orang tetap mau berkontribusi.",hint:"Akui asal idenya, atau klaim mayoritas / abaikan?"},
{n:52,type:"tf",micro:"Menghargai perbedaan menguatkan tim",q:"Benar atau Salah: Tim di mana anggota takut menyampaikan pendapat berbeda (karena bisa diejek) biasanya membuat keputusan lebih cepat & lebih baik.",answer:false,explain:"Sebaliknya, rasa takut membuat informasi & sudut pandang penting disembunyikan. Tim yang aman untuk berbeda membuat keputusan lebih baik & anggotanya lebih terlibat.",hint:"Menguatkan tim, atau melemahkan?"},
{n:53,type:"mcq",micro:"Skenario: perbedaan pendapat soal fakta",q:"Kamu & anggota lain berbeda soal 'kapan acara sebenarnya dimulai'. Cara menyelesaikan:",options:["Debat sampai satu menyerah","Yang lebih yakin yang benar","Cek sumbernya (pengumuman resmi, tanya panitia) — perbedaan fakta diselesaikan dengan verifikasi, bukan debat"],answer:2,explain:"Perbedaan tentang fakta yang bisa dicek diselesaikan dengan mengecek, bukan dengan adu keyakinan.",hint:"Cek sumbernya, atau debat / adu yakin?"},
{n:54,type:"mcq",micro:"Skenario: kamu terpancing merendahkan",q:"Dalam diskusi, kamu tergoda berkata 'ide kamu konyol'. Sebelum mengucapkannya:",options:["Tahan, ubah jadi: 'Aku khawatir soal X di ide itu. Bisa dijelasin gimana ngatasinnya?'","Ucapkan saja karena 'jujur'","Diam & memutar mata"],answer:0,explain:"Mengubah cemoohan jadi pertanyaan/kekhawatiran spesifik menjaga diskusi produktif & hubungan utuh.",hint:"Ubah jadi kekhawatiran spesifik, atau ucapkan / memutar mata?"},
{n:55,type:"mcq",micro:"Skenario: setelah keputusan, ada yang masih tidak puas",q:"Keputusan tim sudah diambil lewat mekanisme yang disepakati, tapi satu anggota masih terus mengungkit ketidaksetujuannya. Sikap tim:",options:["Memusuhi dia","Ingatkan dengan tenang: 'Kita udah putuskan bareng lewat cara yang kita sepakati. Kekhawatiranmu tercatat. Sekarang ayo kita jalankan.'","Membatalkan keputusan karena dia mengeluh"],answer:1,explain:"Menghormati pendapat berbeda punya batas waktu: setelah keputusan adil diambil, semua diharapkan mendukung. Kekhawatiran boleh dicatat.",hint:"Ingatkan keputusan sudah adil + kekhawatiran tercatat, atau batalkan / musuhi?"},
{n:56,type:"mcq",micro:"Skenario: menghargai perbedaan di grup chat",q:"Anggota menyampaikan pendapat berbeda di grup chat & beberapa membalas dengan emoji tertawa & sindiran. Sikap yang menyehatkan:",options:["Ikut menyindir","Diam & membiarkan","Kembalikan ke isi & nada hormat: 'Poin [nama] menarik. Menurut kalian gimana soal kekhawatiran soal waktunya?' — jangan biarkan sindiran jadi norma"],answer:2,explain:"Di chat, sindiran mudah menular. Mengembalikan diskusi ke isi & nada hormat menjaga ruang tetap aman untuk berbeda pendapat.",hint:"Kembalikan ke isi & hormat, atau ikut menyindir / diam?"},
{n:57,type:"tf",micro:"Menghargai bukan berarti pendapat semua sama nilainya",q:"Benar atau Salah: Menghormati pendapat orang berarti mendengarkannya sungguh-sungguh — tetapi pendapat yang didukung alasan & bukti kuat tetap layak lebih dipertimbangkan daripada pendapat tanpa dasar.",answer:true,explain:"Menghargai orangnya tidak sama dengan menganggap semua pendapat sama kuatnya. Diskusi yang baik tetap menimbang kualitas argumen.",hint:"Semua pendapat sama nilainya, atau dengar semua tapi timbang kualitas argumen?"},
{n:58,type:"mcq",micro:"Skenario: perbedaan pendapat jangka panjang di organisasi",q:"Di organisasi/klub, dua kelompok terus berbeda pandangan soal arah. Sikap yang sehat:",options:["Adakan forum untuk mendengar kedua sisi secara terbuka, cari kompromi atau keputusan lewat mekanisme yang disepakati, & jaga agar perbedaan tidak jadi permusuhan antar kelompok","Salah satu kelompok mendominasi & mengabaikan yang lain","Organisasi pecah tanpa dibicarakan"],answer:0,explain:"Perbedaan pandangan jangka panjang butuh forum terbuka, mekanisme keputusan yang adil, & usaha menjaga hubungan antar kelompok.",hint:"Forum terbuka + mekanisme adil + jaga hubungan, atau dominasi / pecah?"},
{n:59,type:"mcq",micro:"Skenario: kamu menyadari kamu yang keliru",q:"Di tengah debat, kamu sadar pendapat lawan lebih tepat. Sikap yang menghormati (diri sendiri & tim):",options:["Diam & pura-pura tidak berubah pikiran","Akui dengan jujur: 'Setelah dengar penjelasanmu, aku setuju, pendapatku tadi kurang tepat.' — tanpa berlebihan menyalahkan diri","Terus mempertahankan pendapat demi gengsi"],answer:1,explain:"Mengakui saat kamu keliru membuat diskusi tim lebih jujur & mendorong orang lain juga berani mengaku keliru.",hint:"Akui jujur, atau ngotot demi gengsi / diam?"},
{n:60,type:"open",micro:"Skenario menyeluruh",q:"Kamu ketua tim 6 orang. Dalam sebuah rapat penting, tim terpecah tajam menjadi dua kubu soal keputusan besar, suasana mulai panas, dan beberapa mulai saling menyindir. Rancang bagaimana kamu memimpin tim melewati perbedaan pendapat ini dengan menghormati semua pihak & sampai ke keputusan (minimal 6 langkah).",sample:"(1) Hentikan sejenak saat suasana mulai panas: 'Oke, kita berhenti dulu bentar. Ini keputusan penting dan wajar kita punya pandangan beda. Ayo kita bahas dengan cara yang bikin semua kedengeran.' (2) Tetapkan aturan diskusi singkat: bicara bergantian, tidak menyindir atau menyerang pribadi, fokus pada ide dan alasannya. (3) Beri tiap kubu waktu setara untuk menjelaskan pandangan + alasannya, sementara yang lain menyimak tanpa memotong; aku (atau pencatat) menulis poin-poin utama tiap sisi supaya terlihat. (4) Minta tiap kubu mengulang inti pandangan kubu lain dengan adil sampai kubu itu setuju 'ya, itu maksud kami' — ini memaksa semua benar-benar memahami sisi lawan. (5) Cari titik temu: apa yang sebenarnya sama-sama diinginkan kedua kubu (biasanya tujuannya sama, caranya beda)? Tuliskan hal yang sudah disepakati. (6) Eksplorasi opsi: adakah pilihan ketiga yang menggabungkan kekuatan kedua sisi, atau cara membagi sehingga keduanya sebagian terpenuhi? (7) Kalau tetap harus memilih, timbang opsi berdasarkan tujuan tim & batasan (waktu, sumber daya, risiko), lalu putuskan lewat mekanisme yang disepakati (voting atau keputusan ketua dengan masukan semua). (8) Setelah diputuskan, tegaskan: 'Kekhawatiran semua sudah dicatat. Keputusan ini diambil bareng lewat cara yang kita sepakati. Sekarang kita semua dukung dan kasih yang terbaik.' (9) Setelah rapat, hubungi anggota yang tampak paling kecewa secara pribadi untuk memastikan hubungan tetap baik & mereka tetap merasa dihargai.",explain:"Jawaban baik: hentikan saat panas + tetapkan aturan diskusi hormat, beri waktu setara tiap sisi menjelaskan + alasan (dicatat terlihat), wajibkan saling memantulkan sampai diakui, cari titik temu (tujuan sama), eksplorasi opsi gabungan/pembagian, timbang berdasarkan tujuan & batasan lalu putuskan lewat mekanisme disepakati, tegaskan semua dukung + kekhawatiran tercatat, dan follow up pribadi ke yang kecewa.",hint:"Hentikan+aturan diskusi → waktu setara+catat → saling memantulkan → titik temu → opsi gabungan → timbang+putuskan lewat mekanisme → semua dukung → follow up yang kecewa."},

// FASE D — PENALARAN (61-80)
{n:61,type:"mcq",micro:"Mengapa perbedaan pendapat berharga",q:"Mengapa tim yang punya perbedaan pendapat (yang dibahas baik) sering membuat keputusan lebih baik?",options:["Karena perbedaan membuat orang bekerja lebih keras","Perbedaan tidak memengaruhi kualitas keputusan","Perbedaan memaksa tim menimbang beberapa sisi, menguji asumsi, & menangkap risiko atau peluang yang satu sudut pandang lewatkan"],answer:2,explain:"Keputusan yang tidak pernah ditantang sering menyimpan lubang. Perbedaan pendapat adalah 'pengecekan' gratis.",hint:"Menimbang beberapa sisi & menguji asumsi, atau tak berpengaruh?"},
{n:62,type:"mcq",micro:"Mengapa menyerang orang gagal",q:"Mengapa menyerang pribadi ('kamu memang bodoh') saat berbeda pendapat merusak diskusi?",options:["Orang yang merasa diserang beralih ke bertahan diri & tidak lagi mendengar isi; masalah inti tidak terselesaikan & hubungan rusak","Karena itu melanggar aturan","Justru membuat orang cepat setuju"],answer:0,explain:"Kritik ide bisa didengar; serangan pribadi menutup telinga & membakar jembatan.",hint:"Memicu pertahanan & merusak hubungan, atau membuat cepat setuju?"},
{n:63,type:"tf",micro:"Groupthink",q:"Benar atau Salah: 'Groupthink' terjadi ketika anggota tim menahan pendapat berbeda demi keharmonisan, sehingga tim mengambil keputusan buruk yang sebenarnya diragukan banyak orang secara diam-diam.",answer:true,explain:"Keharmonisan palsu (semua diam & mengangguk) berbahaya. Menyuarakan keraguan dengan hormat justru melindungi tim.",hint:"Groupthink = menahan pendapat demi harmoni, atau tim yang sehat?"},
{n:64,type:"mcq",micro:"Menilai diskusi yang sehat",q:"Tanda diskusi tentang perbedaan pendapat berjalan sehat:",options:["Semua langsung setuju tanpa membahas","Fokus pada ide & alasan, semua merasa didengar, orang boleh berubah pikiran tanpa diejek, & hubungan tetap baik setelahnya","Yang paling keras selalu menang"],answer:1,explain:"Diskusi sehat = pertukaran ide yang jujur di mana orang tetap aman & dihargai, apa pun hasilnya.",hint:"Fokus ide + semua didengar + hubungan utuh, atau yang keras menang / langsung setuju?"},
{n:65,type:"mcq",micro:"Mengapa memantulkan pendapat lawan membantu",q:"Meminta tiap pihak mengulang pendapat lawan sampai lawan setuju 'itu maksudku' berguna karena...",options:["Membuat diskusi lebih lama tanpa manfaat","Memaksa satu pihak menyerah","Memastikan kedua pihak benar-benar memahami perbedaan yang sebenarnya, bukan berdebat dengan versi karikatur satu sama lain"],answer:2,explain:"Banyak 'perbedaan pendapat' sebenarnya salah paham. Memantulkan mengungkap apakah perbedaannya nyata & di mana persisnya.",hint:"Memastikan paham perbedaan sebenarnya, atau memperlama?"},
{n:66,type:"tf",micro:"Menghormati = tidak boleh tegas?",q:"Benar atau Salah: Menghormati pendapat orang lain berarti kamu tidak boleh menyampaikan ketidaksetujuanmu dengan tegas.",answer:false,explain:"Sebaliknya, kamu bisa sangat tegas soal ISI ('aku benar-benar tidak setuju karena X') sambil tetap hormat soal CARA (nada tenang, fokus ide, mengakui usaha). Tegas dan hormat bisa bersama.",hint:"Hormat = tidak boleh tegas, atau bisa tegas isi + hormat cara?"},
{n:67,type:"mcq",micro:"Perbedaan pendapat & kepercayaan tim",q:"Mengapa tim yang bisa membahas perbedaan pendapat dengan hormat justru lebih saling percaya?",options:["Anggota tahu bahwa bila mereka punya keraguan, mereka bisa menyuarakannya & akan didengar — bukan harus menebak apakah aman","Karena mereka tidak pernah berbeda","Perbedaan pendapat tidak memengaruhi kepercayaan"],answer:0,explain:"Kepercayaan tumbuh dari 'aku bisa jujur di sini'. Tim yang menghukum perbedaan mengajarkan anggota untuk menyembunyikan.",hint:"Anggota tahu keraguan akan didengar, atau tak berpengaruh?"},
{n:68,type:"mcq",micro:"Perbedaan pendapat yang berbasis identitas/keyakinan",q:"Untuk perbedaan yang menyentuh keyakinan atau identitas pribadi (agama, budaya, nilai keluarga), sikap dalam kerja tim:",options:["Menganggap yang berbeda keyakinan tidak bisa diajak kerja sama","Fokus pada tugas & tujuan bersama; hormati bahwa perbedaan itu ada tanpa harus 'memenangkannya'; hindari memaksakan keyakinan pribadi ke anggota lain","Perdebatkan sampai satu pihak 'kalah'"],answer:1,explain:"Sebagian perbedaan tidak untuk 'diselesaikan' dalam tim. Yang penting: saling menghormati & fokus pada tujuan bersama.",hint:"Hormati + fokus tujuan bersama, atau perdebatkan sampai menang / tolak kerja sama?"},
{n:69,type:"mcq",micro:"Menilai apakah suatu perbedaan perlu diperjuangkan",q:"Sebelum memperjuangkan pendapatmu dengan keras, pertimbangkan:",options:["Selalu perjuangkan setiap pendapat sekuat mungkin","Tidak pernah menyampaikan pendapat","Seberapa besar dampaknya pada hasil? Apakah ini soal fakta/prinsip penting, atau selera/detail kecil? Apakah aku yakin atau hanya tidak mau kalah?"],answer:2,explain:"Memilih 'pertempuran' dengan bijak — memperjuangkan yang penting, melepaskan yang kecil — membuat suaramu lebih dihargai saat benar-benar dibutuhkan.",hint:"Timbang dampak & motivasi, atau perjuangkan semua / diam semua?"},
{n:70,type:"order",micro:"Dari terpancing ke tanggapan yang menghormati",q:"Urutkan proses saat kamu terpancing ingin merendahkan pendapat orang.",items:["Kenali reaksimu: dada panas, ingin berkata 'itu konyol'","Beri jeda: tarik napas, tahan respons","Cari: apa yang mungkin masuk akal / benar dari pendapat itu?","Sampaikan kekhawatiranmu sebagai pertanyaan/poin spesifik soal ide, dengan nada tenang"],answer:[0,1,2,3],explain:"Kenali → jeda → cari sisi baik → sampaikan sebagai poin spesifik. Jeda memisahkan cemoohan dari tanggapan yang berguna.",hint:"Apa yang perlu disadari sebelum memberi jeda?"},
{n:71,type:"mcq",micro:"Perbedaan pendapat & pembelajaran",q:"Bekerja dalam tim yang sering berbeda pendapat (dengan hormat) membuat kamu...",options:["Terbiasa menimbang sudut pandang lain, menguji asumsimu sendiri, & lebih fleksibel dalam berpikir","Selalu bingung & tidak berkembang","Kehilangan pendirian"],answer:0,explain:"Berlatih menghadapi perbedaan pendapat melatih pikiran untuk lebih terbuka & teliti — keterampilan berharga di mana pun.",hint:"Melatih berpikir fleksibel & teliti, atau membuat bingung?"},
{n:72,type:"tf",micro:"Menghormati perbedaan lintas budaya",q:"Benar atau Salah: Cara menyampaikan ketidaksetujuan sama persis di semua budaya & keluarga, jadi tidak perlu khawatir salah menafsir maksud orang.",answer:false,explain:"Sebaliknya, sebagian budaya/keluarga sangat langsung, sebagian sangat halus. Yang halus bisa terlewat oleh orang dari budaya langsung; yang langsung bisa terasa kasar bagi yang lain. Menyadari ini mengurangi salah paham.",hint:"Cara menyampaikan beda antar budaya, atau universal?"},
{n:73,type:"mcq",micro:"Menghormati & tanggung jawab",q:"Menghormati pendapat berbeda datang dengan tanggung jawab, yaitu...",options:["Selalu mengalah","Menyampaikan pendapatmu sendiri dengan jujur & beralasan juga — bukan hanya mendengar lalu diam","Selalu menyembunyikan pendapatmu"],answer:1,explain:"Diskusi yang sehat butuh semua pihak menyumbang pandangan. 'Menghormati' bukan berarti menghilangkan suaramu sendiri.",hint:"Sampaikan pandanganmu juga, atau hanya dengar lalu diam?"},
{n:74,type:"mcq",micro:"Menilai 'debat kusir'",q:"'Debat kusir' (berdebat hanya untuk menang, bukan mencari kebenaran) dikenali dari...",options:["Orang saling mengakui poin & mencari solusi","Diskusi yang tenang & fokus ide","Orang tidak pernah mengakui poin lawan, mengganti-ganti argumen saat kalah, menyerang pribadi, & tujuannya jelas menang bukan memahami"],answer:2,explain:"Kalau lawan bicara tidak pernah bergerak & hanya mau menang, kadang lebih baik menghentikan diskusi daripada terus terpancing.",hint:"Tidak pernah mengakui + tujuannya menang, atau saling mengakui + cari solusi?"},
{n:75,type:"tf",micro:"Perbedaan pendapat setelah keputusan",q:"Benar atau Salah: Setelah tim mengambil keputusan lewat proses yang adil & disepakati, anggota yang tadinya tidak setuju diharapkan tetap mendukung & menjalankan keputusan itu dengan baik ('tidak setuju, tetap komit').",answer:true,explain:"Menghormati proses berarti menerima hasilnya. Terus menyabotase atau mengungkit setelah keputusan adil merusak tim.",hint:"Dukung setelah proses adil, atau boleh sabotase / ungkit terus?"},
{n:76,type:"mcq",micro:"Perbedaan pendapat & kualitas pemimpin",q:"Pemimpin tim yang baik terhadap perbedaan pendapat...",options:["Sengaja mengundang pandangan berbeda ('ada yang lihat risiko di rencana ini?'), tidak menghukum yang berbeda, & memfasilitasi keputusan yang adil","Menekan semua yang tidak setuju dengannya","Menghindari keputusan apa pun agar tidak ada yang kecewa"],answer:0,explain:"Pemimpin yang hanya dikelilingi orang yang setuju kehilangan informasi penting. Mengundang perbedaan adalah tanda pemimpin kuat.",hint:"Mengundang perbedaan + memfasilitasi, atau menekan / menghindari keputusan?"},
{n:77,type:"mcq",micro:"Perbedaan pendapat & rasa memiliki",q:"Anggota yang pendapatnya didengar & dipertimbangkan (meski tidak selalu dipakai) cenderung...",options:["Tidak peduli pada hasil","Lebih mendukung keputusan akhir & lebih terlibat, karena merasa jadi bagian dari proses","Selalu kecewa & menarik diri"],answer:1,explain:"Rasa 'aku didengar' membuat orang menerima hasil yang bukan pilihannya jauh lebih lapang.",hint:"Lebih mendukung & terlibat, atau kecewa & menarik diri?"},
{n:78,type:"mcq",micro:"Menghormati vs toleransi terhadap yang menyakiti",q:"Menghormati perbedaan pendapat TIDAK berarti tim harus menoleransi...",options:["Pandangan berbeda soal strategi proyek","Kritik yang disampaikan dengan sopan","Ucapan yang menghina, merendahkan kelompok tertentu, atau menyerang pribadi anggota"],answer:2,explain:"Ada batas: menghormati perbedaan ide berbeda dari membiarkan perilaku yang melukai atau merendahkan orang.",hint:"Menghina & merendahkan orang, atau pandangan berbeda soal strategi?"},
{n:79,type:"mcq",micro:"Perbedaan pendapat & waktu",q:"Kapan sebuah perbedaan pendapat sebaiknya dibiarkan tidak terselesaikan (agree to disagree)?",options:["Bila tidak memengaruhi hasil/tindakan yang perlu diambil, atau bila lebih menyangkut selera/nilai pribadi yang tidak perlu diseragamkan","Tidak pernah — semua perbedaan harus ada pemenang","Selalu — jangan pernah menyelesaikan perbedaan"],answer:0,explain:"Menghabiskan energi menyelesaikan perbedaan yang tidak penting membuang waktu & bisa merusak hubungan tanpa manfaat.",hint:"Bila tidak memengaruhi hasil / soal selera, atau selalu harus ada pemenang?"},
{n:80,type:"open",micro:"Membandingkan dua tim",q:"Tim A: anggota yang berbeda pendapat langsung diejek 'sok tahu', semua akhirnya diam & mengikuti ketua, keputusan diambil cepat tapi ternyata punya lubang besar yang beberapa anggota sebenarnya sudah lihat. Tim B: perbedaan pendapat didengar, dibahas dengan fokus ide, keputusan lebih lambat tapi lebih matang, anggota yang kalah suara tetap mendukung. Jelaskan mengapa Tim B lebih sehat & kemungkinan lebih sukses jangka panjang (minimal 4 alasan), dan 1 kelemahan pendekatan Tim B yang perlu dikelola.",sample:"Tim B lebih sehat & kemungkinan lebih sukses karena: (1) Keputusan Tim B lebih matang karena diuji dari beberapa sudut — lubang seperti yang dialami Tim A lebih mungkin ketahuan sebelum terlambat. (2) Anggota Tim B merasa aman menyuarakan keraguan, jadi informasi penting tidak disembunyikan; di Tim A, orang yang melihat masalah memilih diam karena takut diejek. (3) Anggota Tim B lebih terlibat dan mendukung keputusan akhir karena merasa didengar, sementara anggota Tim A hanya patuh di permukaan dan mungkin diam-diam tidak berkomitmen. (4) Hubungan dalam Tim B tetap baik karena perbedaan difokuskan pada ide, bukan pribadi; di Tim A, ejekan 'sok tahu' merusak kepercayaan dan membuat orang enggan berkontribusi lagi. (5) Dalam jangka panjang, Tim B belajar dan makin efektif tiap proyek, sedangkan Tim A akan terus membuat keputusan berlubang karena tidak ada yang berani mengoreksi. Kelemahan pendekatan Tim B yang perlu dikelola: diskusi bisa berlarut-larut dan lambat kalau tidak dibatasi. Tim B perlu menetapkan batas waktu diskusi dan mekanisme keputusan yang jelas, supaya menghargai perbedaan pendapat tidak berubah menjadi kebuntuan.",explain:"Jawaban baik memberi minimal 4 alasan Tim B lebih sehat (keputusan lebih matang/teruji, informasi tidak disembunyikan karena aman, anggota lebih terlibat & mendukung, hubungan terjaga karena fokus ide, tim belajar & membaik) dan 1 kelemahan yang perlu dikelola (diskusi bisa berlarut/lambat — perlu batas waktu & mekanisme keputusan).",hint:"Alasan B: keputusan teruji, info tidak disembunyikan, anggota terlibat, hubungan terjaga, tim membaik. Kelemahan: bisa lambat/berlarut — perlu batas waktu + mekanisme."},

// FASE E — TANTANGAN (81-100)
{n:81,type:"mcq",micro:"Kasus: perbedaan pendapat & anggota yang tidak pernah mengalah",q:"Seorang anggota tidak pernah mau bergerak dari pendapatnya, tidak memberi alasan baru, & tujuannya jelas hanya menang. Sikap tim:",options:["Terus berdebat tanpa akhir","Setelah memberinya kesempatan penuh menjelaskan & didengar, jalankan mekanisme keputusan yang disepakati; diskusi tidak bisa disandera satu orang yang menolak semua","Selalu menuruti dia agar diskusi selesai"],answer:1,explain:"Menghormati berarti mendengar sungguh-sungguh; tapi tim tidak bisa lumpuh karena satu orang menolak proses. Setelah didengar, keputusan diambil lewat mekanisme.",hint:"Dengar penuh lalu jalankan mekanisme, atau selalu turuti / debat tanpa akhir?"},
{n:82,type:"mcq",micro:"Kasus: kamu diminta memihak",q:"Dua teman tim berbeda pendapat & masing-masing mendesakmu 'kamu di pihak siapa?'. Sikap:",options:["Pilih pihak teman yang lebih dekat","Menghindari rapat","'Aku nggak mau ini jadi soal pihak. Aku dengar dua-duanya. Poin [nama] soal X kuat, poin [nama] soal Y juga. Gimana kalau kita...' — nilai berdasarkan ide, bukan orang"],answer:2,explain:"Perbedaan pendapat tim bukan pertandingan tim. Menolak membingkainya sebagai 'pihak' & menilai berdasarkan ide menjaga tim tetap satu.",hint:"Nilai berdasarkan ide + tolak 'pihak', atau pilih teman dekat / kabur?"},
{n:83,type:"tf",micro:"Refleksi: menghargai perbedaan = kekuatan tim",q:"Benar atau Salah: Tim yang sering menghadapi perbedaan pendapat pasti tim yang bermasalah; tim yang benar-benar matang hampir tidak pernah berbeda pendapat.",answer:false,explain:"Sebaliknya, tim lemah pecah atau membisu saat berbeda pendapat. Tim matang & kuat justru menghadapinya dengan hormat & menggunakannya untuk keputusan lebih baik.",hint:"Tanda tim matang, atau tanda tim bermasalah?"},
{n:84,type:"mcq",micro:"Kasus: menghargai perbedaan saat kamu punya kuasa",q:"Kamu ketua & punya wewenang memutuskan. Seorang anggota junior menyampaikan pandangan berbeda dengan sopan. Sikap yang menghormati:",options:["Dengarkan sungguh-sungguh & timbang isinya; jelaskan alasan keputusanmu bila berbeda; jangan pakai wewenang untuk membungkam atau mempermalukannya","Tolak langsung karena kamu yang berwenang","Anggap dia menantang otoritasmu"],answer:0,explain:"Wewenang untuk memutuskan bukan izin mengabaikan atau membungkam pandangan berbeda. Pemimpin yang mendengar membuat keputusan lebih baik.",hint:"Dengar + jelaskan alasan, atau tolak karena berwenang / anggap menantang?"},
{n:85,type:"order",micro:"Menyelesaikan perbedaan pendapat yang menyentuh nilai",q:"Urutkan cara tim menyelesaikan perbedaan yang menyangkut nilai/prioritas (mis. 'utamakan kecepatan' vs 'utamakan kualitas').",items:["Akui bahwa ini perbedaan prioritas, bukan soal siapa yang 'benar'","Minta tiap pihak menjelaskan mengapa prioritas itu penting baginya","Cari keseimbangan: bagian mana yang butuh kualitas tinggi, bagian mana yang cukup cepat & sederhana","Sepakati keseimbangan itu bersama & jalankan"],answer:[0,1,2,3],explain:"Akui ini soal prioritas → pahami alasan tiap pihak → cari keseimbangan per bagian → sepakati. Bukan pembuktian menang-kalah.",hint:"Apa yang diakui sebelum mencari keseimbangan?"},
{n:86,type:"mcq",micro:"Kasus: perbedaan pendapat & tekanan waktu berulang",q:"Timmu selalu 'tidak sempat' membahas perbedaan pendapat karena tenggat, jadi selalu ikut suara terkeras. Solusi jangka panjang:",options:["Berhenti punya pendapat","Jadwalkan diskusi keputusan penting lebih awal (bukan di detik terakhir) & sepakati mekanisme keputusan cepat yang tetap mendengar semua (mis. tiap orang 1 menit, lalu voting)","Terima saja selalu ikut yang terkeras"],answer:1,explain:"Pola 'tidak sempat' sering karena keputusan dibahas terlalu telat. Membahas lebih awal + mekanisme cepat menjaga perbedaan tetap didengar.",hint:"Bahas lebih awal + mekanisme cepat yang mendengar semua, atau ikut yang terkeras?"},
{n:87,type:"tf",micro:"Menghargai perbedaan pendapat berlaku dua arah",q:"Benar atau Salah: Menghormati perbedaan pendapat berarti kamu berhak menyampaikan pandanganmu dengan sopan DAN kamu menghormati hak orang lain untuk berpandangan berbeda darimu.",answer:true,explain:"Ini timbal balik: kamu menyuarakan diri dengan hormat, & memberi ruang yang sama bagi orang lain — termasuk saat mereka tidak setuju denganmu.",hint:"Timbal balik, atau hanya hakmu?"},
{n:88,type:"mcq",micro:"Kasus: perbedaan pendapat memicu perpecahan tim",q:"Perbedaan pendapat yang tidak dikelola sudah membuat tim terbelah & saling dingin. Langkah pemulihan:",options:["Biarkan sampai proyek selesai lalu bubar","Salah satu kelompok mendominasi & mengabaikan yang lain","Adakan pertemuan khusus: akui masalahnya terbuka, tetapkan aturan bicara hormat, dengar kedua sisi penuh, cari titik temu & keputusan lewat mekanisme adil, & tegaskan komitmen tetap satu tim"],answer:2,explain:"Perpecahan yang sudah terjadi butuh pertemuan yang sengaja untuk membicarakannya, bukan dibiarkan atau diselesaikan dengan dominasi.",hint:"Pertemuan khusus untuk membicarakan + mekanisme adil, atau biarkan / dominasi?"},
{n:89,type:"mcq",micro:"Kasus: kamu benar tapi tim memilih salah",q:"Tim, setelah mendengar kekhawatiranmu, tetap memilih rencana yang menurutmu keliru. Beberapa minggu kemudian, masalah yang kamu peringatkan benar-benar terjadi. Sikap yang matang:",options:["Bantu tim mengatasi masalah sekarang tanpa berkata 'kan aku sudah bilang'; setelah tenang, sarankan agar lain kali kekhawatiran yang spesifik ditimbang lebih serius","'Tuh kan, kalian sih nggak dengerin aku!' berulang-ulang","Menolak membantu karena 'itu akibat pilihan kalian'"],answer:0,explain:"Membuktikan 'aku benar' dengan menyalahkan hanya merusak tim. Membantu mengatasi + memberi masukan proses ke depan jauh lebih berharga.",hint:"Bantu atasi + masukan proses, atau 'kan aku bilang' / menolak bantu?"},
{n:90,type:"open",micro:"Kasus menyeluruh",q:"Kamu akan memimpin tim OSIS 8 orang selama setahun. Kamu tahu tim ini punya beberapa anggota yang keras & suka mendominasi, dan beberapa yang sangat pendiam. Rancang bagaimana kamu membangun budaya tim di mana perbedaan pendapat dihargai — semua berani bersuara, diskusi tetap hormat, dan keputusan tetap bisa diambil. Minimal 6 praktik konkret dengan alasan.",sample:"(1) Di awal, tim membuat kesepakatan bersama soal cara berdiskusi: bicara bergantian, kritik ide bukan orang, tidak menyindir/mengejek, semua pendapat didengar sebelum keputusan. Alasan: aturan yang disepakati bersama lebih dipatuhi & memberi rasa aman. (2) Dalam rapat, aku sengaja meminta pendapat anggota pendiam lebih dulu atau secara khusus ('menurutmu gimana, [nama]?') sebelum yang keras mengisi ruang. Alasan: setelah suara keras mendominasi, yang pendiam sulit bicara. (3) Untuk topik penting, aku minta tiap orang menulis pendapatnya dulu (di kertas/chat) sebelum diskyci lisan. Alasan: menulis dulu membuat yang lambat berpikir & yang pendiam tetap tersampaikan, tidak tenggelam. (4) Aku menegakkan aturan diskusi secara konsisten & sama untuk semua — kalau ada yang menyindir atau memotong, aku ingatkan dengan tenang, termasuk kepada anggota yang keras & teman dekatku. Alasan: penegakan pilih-pilih menghancurkan kepercayaan pada aturan. (5) Aku memakai mekanisme keputusan yang jelas (dengar semua → cari titik temu → kalau perlu voting), dengan batas waktu diskusi supaya menghargai perbedaan tidak jadi kebuntuan. Alasan: tim tetap harus bisa bergerak. (6) Aku menghargai secara terbuka orang yang menyampaikan pandangan berbeda dengan baik & orang yang berubah pikiran setelah mendengar argumen — tidak mengejek 'nah kan'. Alasan: kalau berbeda pendapat & mengaku keliru dihukum, orang akan menyembunyikannya. (7) Setelah keputusan, aku menegaskan 'kekhawatiran semua tercatat, keputusan diambil bareng, sekarang kita dukung' & follow up pribadi ke yang kecewa. (8) Berkala, tim merefleksikan: apakah semua merasa didengar? apa yang perlu diperbaiki soal cara kita berdiskusi?",explain:"Jawaban baik memuat minimal 6 praktik konkret dengan alasan: kesepakatan cara berdiskusi bersama, sengaja meminta pendapat yang pendiam lebih dulu, menulis pendapat sebelum diskusi lisan, menegakkan aturan diskusi konsisten untuk semua (termasuk yang keras & teman), mekanisme keputusan jelas + batas waktu, menghargai yang berbeda pendapat & yang berubah pikiran (tidak mengejek), menegaskan dukungan setelah keputusan + follow up yang kecewa, refleksi berkala.",hint:"Bangun budaya: kesepakatan diskusi, ruang untuk yang pendiam (tanya duluan/tulis dulu), penegakan konsisten, mekanisme keputusan + batas waktu, hargai perbedaan & perubahan pikiran, dukungan setelah keputusan, refleksi."},
{n:91,type:"mcq",micro:"Kasus: perbedaan pendapat di media sosial/publik",q:"Seorang anggota tim memposting pendapat pribadi (bukan atas nama tim) yang berbeda dari mayoritas tim. Sikap:",options:["Menyerang balik di media sosial","Itu haknya sebagai individu; selama tidak mengatasnamakan tim atau menyerang anggota lain, tim menghormati kebebasan berpendapat pribadinya","Menuntut dia menghapus post karena 'malu-maluin tim'"],answer:1,explain:"Menghormati perbedaan termasuk menghormati bahwa anggota tim adalah individu dengan pandangan sendiri di luar konteks tim.",hint:"Hormati kebebasan pribadinya (selama tidak atas nama tim / menyerang), atau tuntut hapus / serang balik?"},
{n:92,type:"tf",micro:"Refleksi: perbedaan pendapat bukan musuh kerja sama",q:"Benar atau Salah: Perbedaan pendapat bukanlah lawan dari kerja sama — justru kerja sama yang baik adalah kemampuan sekelompok orang dengan pandangan berbeda untuk tetap bekerja menuju tujuan bersama dengan saling menghormati.",answer:true,explain:"Kalau kerja sama berarti 'semua harus berpikir sama', ia rapuh & miskin ide. Kerja sama sejati merangkul perbedaan.",hint:"Perbedaan lawan kerja sama, atau bagian darinya?"},
{n:93,type:"mcq",micro:"Kasus: menghargai saat lelah & tertekan",q:"Kamu lelah & tertekan, & seorang anggota menyampaikan pendapat berbeda yang membuatmu ingin menyahut kasar. Sikap:",options:["Sahut kasar saja, 'kan capek'","Diam & memusuhi dia","Sadari kondisimu: 'Maaf, aku lagi capek. Boleh kita bahas ini nanti setelah aku bisa mikir lebih jernih?' — tunda daripada merespons kasar"],answer:2,explain:"Kondisimu memengaruhi caramu menanggapi. Menunda dengan jujur lebih baik daripada merusak diskusi & hubungan karena lelah.",hint:"Sadari kondisi + tunda, atau sahut kasar / memusuhi?"},
{n:94,type:"mcq",micro:"Kasus: perbedaan pendapat & keadilan bagi yang minoritas",q:"Dalam tim, satu anggota selalu jadi minoritas dalam setiap keputusan & mulai merasa suaranya tidak berarti. Sikap tim:",options:["Pastikan pendapatnya benar-benar didengar & ditimbang tiap kali (bukan sekadar formalitas); cari keputusan yang sesekali mengakomodasi pandangannya bila masuk akal; akui kontribusinya","Biarkan, dia memang selalu kalah suara","Suruh dia berhenti punya pendapat berbeda"],answer:0,explain:"Selalu kalah suara berbeda dari tidak didengar. Tim yang sehat memastikan minoritas benar-benar ditimbang & sesekali diakomodasi bila beralasan.",hint:"Pastikan benar-benar didengar & sesekali diakomodasi, atau biarkan / suruh diam?"},
{n:95,type:"tf",micro:"Menghargai perbedaan = mendengar, bukan menyerah",q:"Benar atau Salah: Menghormati pendapat yang berbeda pada dasarnya berarti mengalah & mengikuti pendapat itu, agar tidak ada yang tersinggung.",answer:false,explain:"Sebaliknya, menghargai berarti mendengarkan dengan serius & mempertimbangkan — bukan otomatis menyerah atau membiarkan yang paling keras selalu menang. Ini tentang proses yang adil, bukan siapa yang mengalah.",hint:"Mendengar & menimbang serius, atau otomatis menyerah / yang keras menang?"},
{n:96,type:"mcq",micro:"Kasus: refleksi soal cara kamu menghadapi perbedaan",q:"Cara melatih dirimu menghadapi perbedaan pendapat lebih baik:",options:["Tidak pernah mengevaluasi","Setelah diskusi: apakah aku benar-benar mendengar sisi lain? apakah aku menyerang ide atau orang? apakah aku terbuka berubah pikiran? apa satu hal yang akan kuperbaiki?","Menyimpulkan orang lain yang tidak bisa menghargai"],answer:1,explain:"Meninjau caramu sendiri menghadapi perbedaan (bukan hanya menilai orang lain) mempercepat kamu jadi rekan diskusi yang lebih baik.",hint:"Evaluasi caramu sendiri, atau menyalahkan orang lain / tak pernah?"},
{n:97,type:"mcq",micro:"Prinsip inti bab ini",q:"Pesan inti menghargai perbedaan pendapat:",options:["Hindari semua perbedaan dengan diam","Menangkan setiap perbedaan pendapat","Anggap perbedaan pendapat wajar & berpotensi berguna; dengar sampai paham; kritik ide bukan orang; sampaikan pandanganmu dengan alasan & nada hormat; cari titik temu & putuskan bersama lewat mekanisme adil; dukung keputusan meski bukan pilihanmu; jaga hubungan"],answer:2,explain:"Ringkasan: wajar & berguna + dengar sampai paham + kritik ide bukan orang + alasan + nada hormat + titik temu + mekanisme adil + dukung hasil + jaga hubungan.",hint:"Wajar & berguna, dengar, kritik ide, alasan+hormat, titik temu, mekanisme adil, dukung hasil, jaga hubungan — rangkai."},
{n:98,type:"tf",micro:"Refleksi: menghargai perbedaan melayani hasil & hubungan",q:"Benar atau Salah: Menghargai perbedaan pendapat dengan baik menghasilkan dua hal: keputusan yang lebih matang & teruji, DAN hubungan tim yang tetap solid meski anggota sering berbeda pandangan.",answer:true,explain:"Kalau keputusan matang tapi tim jadi saling dingin, atau tim akur tapi keputusan berlubang karena tidak ada yang berani berbeda — keduanya belum berhasil.",hint:"Keputusan matang + hubungan solid, atau salah satu?"},
{n:99,type:"mcq",micro:"Kasus: memulai kebiasaan menghargai perbedaan",q:"Cara termudah mulai jadi lebih baik dalam menghargai perbedaan pendapat minggu ini:",options:["Saat seseorang menyampaikan pendapat berbeda, latih satu hal: tahan reaksi awal, tanyakan 'apa yang bikin kamu berpikir begitu?', & dengarkan jawabannya penuh sebelum menanggapi","Menunggu tim yang lebih dewasa","Berhenti menyampaikan pendapat agar tidak ada perbedaan"],answer:0,explain:"Kebiasaan menghargai perbedaan dimulai dari satu tindakan kecil: menahan reaksi & bertanya alasan sebelum membantah.",hint:"Latih tahan reaksi + tanya alasan, atau menunggu / berhenti berpendapat?"},
{n:100,type:"open",micro:"Refleksi & aturan pribadi menghargai perbedaan",q:"Tulis 'aturan pribadi tentang menghargai perbedaan pendapat' berisi minimal 5 poin yang akan kamu pegang, masing-masing dengan alasan singkat.",sample:"Contoh aturan pribadi: (1) Aku menganggap perbedaan pendapat sebagai hal wajar & kesempatan menemukan keputusan lebih baik, bukan tanda konflik — karena tim yang selalu setuju sering tidak memeriksa kesalahannya. (2) Sebelum membantah, aku mendengarkan pendapat orang sampai selesai & mengulang intinya untuk memastikan aku paham — karena banyak 'perbedaan' sebenarnya salah paham. (3) Aku mengkritik ide, bukan orangnya, dan menyampaikannya dengan alasan spesifik & nada tenang — karena serangan pribadi menutup telinga & merusak hubungan. (4) Aku menahan reaksi 'itu konyol' & menggantinya dengan pertanyaan 'apa yang bikin kamu berpikir begitu?' — karena reaksi cepat sering emosi & meleset. (5) Aku bersedia mengubah pendapatku bila ada argumen lebih baik, dan aku tidak mengejek orang yang berubah pikiran — karena keterbukaan adalah kekuatan, bukan kelemahan. (6) Setelah tim memutuskan lewat cara yang adil, aku mendukung keputusan itu meski bukan pilihanku, sambil boleh mencatat kekhawatiranku — karena menghormati proses berarti menerima hasilnya. (7) Aku menegaskan bahwa perbedaan pendapat soal ide tidak mengubah hubungan: 'kita beda pendapat, tapi tetap satu tim'.",explain:"Jawaban baik memuat minimal 5 aturan konkret dengan alasan, mencakup ide inti bab: anggap perbedaan wajar & berguna, dengar sampai paham + pantulkan, kritik ide bukan orang + alasan + nada tenang, tahan reaksi & tanya alasan, terbuka berubah pikiran & tidak mengejek yang berubah, dukung keputusan adil meski bukan pilihan, jaga hubungan (soal ide bukan pribadi).",hint:"Ambil satu pelajaran tiap fase — perbedaan wajar & berguna, dengar+pantulkan, kritik ide+alasan+nada, tahan reaksi+tanya alasan, terbuka berubah, dukung keputusan adil, jaga hubungan — jadikan aturan 'aku akan...'."},
];
